import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.ouUSJJSK.js";var i=JSON.parse(`{"title":"eLearning Server 5G Документация","description":"","frontmatter":{},"headers":[],"relativePath":"guide/reference.md","filePath":"guide/reference.md"}`),a={name:`guide/reference.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="elearning-server-5g-документация" tabindex="-1">eLearning Server 5G Документация <a class="header-anchor" href="#elearning-server-5g-документация" aria-label="Permalink to “eLearning Server 5G Документация”">​</a></h1><p><em>LMS/LXP нового поколения с нейросетевой поддержкой: курсы, вебинары, адаптация, оценка, мотивация и проактивные коммуникации</em></p><p><strong>Версия:</strong> 5G · <strong>Редакция:</strong> Enterprise · <strong>Язык:</strong> RU · <strong>Обновлено:</strong> 2026-08-19</p><hr><h2 id="описание-системы-документации" tabindex="-1">Описание системы документации <a class="header-anchor" href="#описание-системы-документации" aria-label="Permalink to “Описание системы документации”">​</a></h2><p>Документация <strong>eLearning Server 5G</strong> — единый источник правил, сценариев и инструкций по работе платформы. Портал помогает быстро внедрить обучение, настроить мотивацию и коммуникации, запустить адаптационные программы и оценку персонала, а также обеспечить измеримость результатов.</p><h3 id="для-кого" tabindex="-1">Для кого <a class="header-anchor" href="#для-кого" aria-label="Permalink to “Для кого”">​</a></h3><ul><li><strong>Администратор LMS/LXP</strong> — роли, права, интеграции, шаблоны, правила мотивации.</li><li><strong>HR/L&amp;D</strong> — треки, механики признания, коммуникационные кампании, аналитика вовлеченности.</li><li><strong>Руководители</strong> — прогресс команд, признание достижений, цели и наставники.</li><li><strong>Авторы курсов</strong> — конструктор, контент, задания и тесты.</li><li><strong>Слушатели</strong> — обучение, участие в сообществах, получение признания.</li></ul><h3 id="рекомендуемая-структура-документации" tabindex="-1">Рекомендуемая структура документации <a class="header-anchor" href="#рекомендуемая-структура-документации" aria-label="Permalink to “Рекомендуемая структура документации”">​</a></h3><ol><li>Быстрый старт и ролевая модель</li><li>Курсы и конструктор (LMS/LXP)</li><li>Вебинарные комнаты и мероприятия</li><li>Оценка и адаптация персонала</li><li><strong>Мотивация и проактивные коммуникации (этот документ)</strong></li><li>Аналитика, отчеты, API и интеграции</li></ol><hr><h2 id="содержание" tabindex="-1">Содержание <a class="header-anchor" href="#содержание" aria-label="Permalink to “Содержание”">​</a></h2><ul><li><a href="#_1-назначение-модуля">1. Назначение модуля</a></li><li><a href="#_2-основные-сущности-и-понятия">2. Основные сущности и понятия</a></li><li><a href="#_3-функции-мотивации-что-получает-организация">3. Функции мотивации</a></li><li><a href="#_4-проактивные-коммуникации-между-пользователями">4. Проактивные коммуникации</a></li><li><a href="#_5-настроика-быстрыи-сценарии-для-администратора-пример">5. Настройка: быстрый сценарий</a></li><li><a href="#_6-сценарии-использования-коротко">6. Сценарии использования</a></li><li><a href="#_7-метрики-и-контроль-эффективности">7. Метрики и контроль эффективности</a></li><li><a href="#_8-рекомендации-по-внедрению-коротко">8. Рекомендации по внедрению</a></li></ul><hr><h1 id="мотивация-и-проактивные-коммуникации-elearning-server-5g" tabindex="-1">Мотивация и проактивные коммуникации (eLearning Server 5G) <a class="header-anchor" href="#мотивация-и-проактивные-коммуникации-elearning-server-5g" aria-label="Permalink to “Мотивация и проактивные коммуникации (eLearning Server 5G)”">​</a></h1><h2 id="_1-назначение-модуля" tabindex="-1">1) Назначение модуля <a class="header-anchor" href="#_1-назначение-модуля" aria-label="Permalink to “1) Назначение модуля”">​</a></h2><p>Модуль «Мотивация и коммуникации» в <strong>eLearning Server 5G</strong> предназначен для:</p><ul><li>формирования <strong>ценности и заметности</strong> сотрудников/слушателей через прозрачные механики признания;</li><li>развития культуры <strong>здорового стремления к признанию</strong> (за вклад, прогресс, экспертность, помощь другим);</li><li>запуска <strong>проактивных коммуникаций</strong> (умные напоминания, рекомендации, приглашения в группы/вебинары) на основе поведения и контекста обучения;</li><li>повышения вовлеченности без спама — за счет лимитов частоты и учета предпочтений пользователя.</li></ul><hr><h2 id="_2-основные-сущности-и-понятия" tabindex="-1">2) Основные сущности и понятия <a class="header-anchor" href="#_2-основные-сущности-и-понятия" aria-label="Permalink to “2) Основные сущности и понятия”">​</a></h2><ul><li><strong>Признание</strong> — публичная или приватная отметка достижения (бейдж, благодарность, отметка в ленте, сообщение от руководителя).</li><li><strong>Баллы/уровни</strong> — внутренняя система прогресса (например, XP), поддерживает уровни и статусы.</li><li><strong>Челленджи</strong> — ограниченные по времени задания (пройти модуль, сдать тест, провести мини-демо, помочь в обсуждении).</li><li><strong>Сообщество/Лента</strong> — LXP-пространство для публикаций, комментариев, вопросов и обмена практиками.</li><li><strong>Проактивные сообщения (Nudges)</strong> — персональные коммуникации, запускаемые триггерами (поведение, дедлайны, пробелы навыков).</li><li><strong>AI-рекомендации</strong> — подсказки по следующим шагам: курс, вебинар, наставник, группа, материал.</li></ul><hr><h2 id="_3-функции-мотивации-что-получает-организация" tabindex="-1">3) Функции мотивации (что получает организация) <a class="header-anchor" href="#_3-функции-мотивации-что-получает-организация" aria-label="Permalink to “3) Функции мотивации (что получает организация)”">​</a></h2><h3 id="_3-1-признание-и-«витрина-достижении»" tabindex="-1">3.1 Признание и «витрина достижений» <a class="header-anchor" href="#_3-1-признание-и-«витрина-достижении»" aria-label="Permalink to “3.1 Признание и «витрина достижений»”">​</a></h3><ul><li>Бейджи за: завершение трека, высокий результат теста, быстрый прогресс, регулярность обучения.</li><li>Бейджи за вклад в сообщество: полезный ответ, публикация кейса, наставничество.</li><li>Виджеты: «Достижения недели», «Новые эксперты», «Лидеры прогресса» (на главной/странице подразделения).</li></ul><h3 id="_3-2-персональная-ценность-и-траектория-развития" tabindex="-1">3.2 Персональная ценность и траектория развития <a class="header-anchor" href="#_3-2-персональная-ценность-и-траектория-развития" aria-label="Permalink to “3.2 Персональная ценность и траектория развития”">​</a></h3><ul><li>Профиль навыков (на основе оценок, завершенных курсов, активности).</li><li>Рекомендации <strong>Next Best Action</strong>: что пройти, где усилиться, к кому обратиться.</li></ul><h3 id="_3-3-челленджи-и-кампании-вовлеченности" tabindex="-1">3.3 Челленджи и кампании вовлеченности <a class="header-anchor" href="#_3-3-челленджи-и-кампании-вовлеченности" aria-label="Permalink to “3.3 Челленджи и кампании вовлеченности”">​</a></h3><ul><li>Кампании (например, «30 дней развития», «Онбординг за 10 дней», «Подготовка к аттестации»).</li><li>Автоприсвоение наград и статусов при выполнении условий.</li></ul><hr><h2 id="_4-проактивные-коммуникации-между-пользователями" tabindex="-1">4) Проактивные коммуникации между пользователями <a class="header-anchor" href="#_4-проактивные-коммуникации-между-пользователями" aria-label="Permalink to “4) Проактивные коммуникации между пользователями”">​</a></h2><h3 id="_4-1-каналы-доставки-пример" tabindex="-1">4.1 Каналы доставки (пример) <a class="header-anchor" href="#_4-1-каналы-доставки-пример" aria-label="Permalink to “4.1 Каналы доставки (пример)”">​</a></h3><ul><li>Внутренние уведомления платформы (центр уведомлений)</li><li>Email</li><li>Корпоративные мессенджеры (при наличии интеграций): Microsoft Teams / Slack / Telegram-бот / VK Teams</li></ul><h3 id="_4-2-типы-проактивных-сценариев" tabindex="-1">4.2 Типы проактивных сценариев <a class="header-anchor" href="#_4-2-типы-проактивных-сценариев" aria-label="Permalink to “4.2 Типы проактивных сценариев”">​</a></h3><ol><li><strong>Поддержка прогресса</strong>: «остался 1 модуль до завершения», «дедлайн через 48 часов».</li><li><strong>Профилактика перегруза</strong>: предложение разбить обучение на микро-шаги, изменить темп.</li><li><strong>Социальное обучение</strong>: приглашение в обсуждение, подбор «учебного партнера», предложение наставника.</li><li><strong>Контекстные подсказки</strong>: рекомендации по курсам/вебинарам в зависимости от роли, компетенций и целей.</li><li><strong>Коммуникации руководителя</strong>: шаблоны признания и точечные сообщения команде.</li></ol><hr><h2 id="_5-настроика-быстрыи-сценарии-для-администратора-пример" tabindex="-1">5) Настройка: быстрый сценарий для администратора (пример) <a class="header-anchor" href="#_5-настроика-быстрыи-сценарии-для-администратора-пример" aria-label="Permalink to “5) Настройка: быстрый сценарий для администратора (пример)”">​</a></h2><h3 id="шаг-1-включите-модуль-мотивации" tabindex="-1">Шаг 1. Включите модуль мотивации <a class="header-anchor" href="#шаг-1-включите-модуль-мотивации" aria-label="Permalink to “Шаг 1. Включите модуль мотивации”">​</a></h3><p><strong>Администрирование → Мотивация → Общие настройки</strong></p><ul><li>Включить: <strong>Бейджи</strong>, <strong>Баллы</strong>, <strong>Публичная лента достижений</strong></li><li>Приватность: <ul><li>разрешить/запретить публикацию достижений в общую ленту;</li><li>разрешить пользователю скрывать достижения в профиле.</li></ul></li></ul><h3 id="шаг-2-создаите-правило-признания-беидж-за-завершение-трека" tabindex="-1">Шаг 2. Создайте правило признания (бейдж за завершение трека) <a class="header-anchor" href="#шаг-2-создаите-правило-признания-беидж-за-завершение-трека" aria-label="Permalink to “Шаг 2. Создайте правило признания (бейдж за завершение трека)”">​</a></h3><p><strong>Мотивация → Бейджи → Создать</strong></p><ul><li>Название: <code>Эксперт: Базовый трек 5G</code></li><li>Условие: <code>Завершен трек &quot;Вводный курс&quot; + тест &gt;= 80%</code></li><li>Публикация: <code>в ленту подразделения</code> + <code>уведомление руководителю</code></li></ul><h3 id="шаг-3-настроите-pro-active-nudges-анти-«застревание»" tabindex="-1">Шаг 3. Настройте pro-active nudges (анти-«застревание») <a class="header-anchor" href="#шаг-3-настроите-pro-active-nudges-анти-«застревание»" aria-label="Permalink to “Шаг 3. Настройте pro-active nudges (анти-«застревание»)”">​</a></h3><p><strong>Коммуникации → Проактивные сценарии → Создать</strong></p><ul><li>Триггер: <code>Нет активности в треке 3 дня</code></li><li>Аудитория: <code>новички (статус &quot;в адаптации&quot;)</code></li><li>Сообщение: <code>персонализируемое (AI)</code>, тон: <code>поддерживающий</code></li><li>Каналы: <code>внутреннее уведомление + email</code></li><li>Ограничение частоты: <code>не чаще 2 раз в неделю на пользователя</code></li></ul><h3 id="шаг-4-включите-«социальныи-ответ»-как-мотивационную-механику" tabindex="-1">Шаг 4. Включите «социальный ответ» как мотивационную механику <a class="header-anchor" href="#шаг-4-включите-«социальныи-ответ»-как-мотивационную-механику" aria-label="Permalink to “Шаг 4. Включите «социальный ответ» как мотивационную механику”">​</a></h3><p><strong>Сообщество → Правила признания</strong></p><ul><li>Начислять баллы за: <ul><li>принятый как полезный ответ;</li><li>публикацию кейса с высоким рейтингом;</li><li>участие в вебинаре (вопрос/комментарий).</li></ul></li></ul><hr><h2 id="_6-сценарии-использования-коротко" tabindex="-1">6) Сценарии использования (коротко) <a class="header-anchor" href="#_6-сценарии-использования-коротко" aria-label="Permalink to “6) Сценарии использования (коротко)”">​</a></h2><h3 id="_6-1-онбординг-и-адаптация" tabindex="-1">6.1 Онбординг и адаптация <a class="header-anchor" href="#_6-1-онбординг-и-адаптация" aria-label="Permalink to “6.1 Онбординг и адаптация”">​</a></h3><ul><li>Челлендж «10 шагов онбординга»</li><li>Автоподбор наставника (по роли/компетенциям)</li><li>Проактивные напоминания о критических задачах адаптации</li></ul><h3 id="_6-2-поддержка-экспертов-и-обмена-знаниями" tabindex="-1">6.2 Поддержка экспертов и обмена знаниями <a class="header-anchor" href="#_6-2-поддержка-экспертов-и-обмена-знаниями" aria-label="Permalink to “6.2 Поддержка экспертов и обмена знаниями”">​</a></h3><ul><li>Бейджи «Эксперт сообщества», «Ментор»</li><li>Подсветка лучших публикаций недели</li><li>Рекомендации подписаться на темы/экспертов</li></ul><h3 id="_6-3-подготовка-к-оценке-аттестации" tabindex="-1">6.3 Подготовка к оценке/аттестации <a class="header-anchor" href="#_6-3-подготовка-к-оценке-аттестации" aria-label="Permalink to “6.3 Подготовка к оценке/аттестации”">​</a></h3><ul><li>AI-рекомендации материалов по пробелам</li><li>План-график подготовки + nudges по дедлайнам</li><li>Признание прогресса (не только результата)</li></ul><hr><h2 id="_7-метрики-и-контроль-эффективности" tabindex="-1">7) Метрики и контроль эффективности <a class="header-anchor" href="#_7-метрики-и-контроль-эффективности" aria-label="Permalink to “7) Метрики и контроль эффективности”">​</a></h2><p><strong>Аналитика → Вовлеченность и мотивация</strong></p><ul><li><strong>Activation Rate</strong> — доля пользователей, начавших обучение в первые <em>N</em> дней</li><li><strong>Completion Rate</strong> — завершение курсов/треков</li><li><strong>Nudge Recovery</strong> — доля вернувшихся к обучению после nudges</li><li><strong>Social Contribution</strong> — вклад в сообщество (посты/комментарии/ответы)</li><li><strong>Recognition Coverage</strong> — насколько равномерно распределено признание (не «только топ-5»)</li></ul><hr><h2 id="_8-рекомендации-по-внедрению-коротко" tabindex="-1">8) Рекомендации по внедрению (коротко) <a class="header-anchor" href="#_8-рекомендации-по-внедрению-коротко" aria-label="Permalink to “8) Рекомендации по внедрению (коротко)”">​</a></h2><ul><li>Начинайте с 2–3 понятных правил признания (за прогресс, регулярность, вклад в сообщество).</li><li>Ограничивайте частоту nudges и дайте пользователю управление предпочтениями уведомлений.</li><li>Делайте признание «за усилие и вклад», а не только «за идеальный результат».</li><li>Связывайте мотивацию с бизнес-целями: адаптация, развитие навыков, качество сервиса, безопасность.</li></ul>`,64)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};